/* AP Psychology Course and Exam Description (2024-25 onward), Unit 3, Development and Learning, topics 3.1–3.9 (as recalled by the author; see the build report).
   https://apcentral.collegeboard.org/courses/ap-psychology/course
   Original wording; every study, dataset and participant described as fictional is invented for practice. Classic findings (Piaget's stage ages,
   Harlow, Ainsworth, Baumrind, Kohlberg, Watson and Rayner, Garcia, Tolman, Bandura, mirror neurons) are hedged where they appear and approximate ages are labelled.
   Gender and sexual orientation are described in the way mainstream psychology and the major professional associations do. Pictures are drawn in code from the stated numbers. */
const fig=(title,o)=>({t:'figure',title,dots:'',...o,hide:Object.keys(o.pts||{}).join('')});
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{}),box:true});
const bars=(title,labels,values)=>({t:'chart',kind:'bars',title,bars:labels.map((label,i)=>({label,value:values[i]}))});
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const scenario=(title,p)=>{const lines=[];let line='';for(const word of p.split(' ')){if((line+' '+word).length>49){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return {t:'board',title,lines};};
const rnd=n=>Math.round(n*1e4)/1e4;
/* dia: boxes placed in pixel units (x right, y up, the picture is 552 wide); links are arrows from one box edge to another; extra holds raw pts, segs and notes */
const dia=(title,nodes,links,extra={},h=192)=>{const pts={},polys=[],segs=[],notes=[];
 nodes.forEach((n,i)=>{Object.assign(pts,{['A'+i]:[n.x,n.y],['B'+i]:[n.x+n.w,n.y],['C'+i]:[n.x+n.w,n.y+n.h],['D'+i]:[n.x,n.y+n.h]});polys.push({v:`A${i}B${i}C${i}D${i}`,col:n.col??i%4});
  const L=n.text.split('|'),cx=n.x+n.w/2,cy=n.y+n.h/2;L.forEach((t,k)=>notes.push({at:[cx,cy+(L.length-1)*7.5-k*15],text:t}));});
 const edge=(n,dx,dy)=>{const t=Math.min(dx?n.w/2/Math.abs(dx):1e9,dy?n.h/2/Math.abs(dy):1e9);return [n.x+n.w/2+dx*t,n.y+n.h/2+dy*t];};
 links.forEach(([a,b],k)=>{const A=nodes[a],B=nodes[b],dx=B.x+B.w/2-A.x-A.w/2,dy=B.y+B.h/2-A.y-A.h/2,p=edge(A,dx,dy),q=edge(B,-dx,-dy),g=4/Math.hypot(dx,dy);
  pts['E'+k]=[p[0]+dx*g,p[1]+dy*g];pts['F'+k]=[q[0]-dx*g,q[1]-dy*g];segs.push({v:`E${k}F${k}`,arrows:1,col:1});});
 Object.assign(pts,extra.pts||{});segs.push(...(extra.segs||[]));notes.push(...(extra.notes||[]));
 return fig(title,{pts,polys,segs,notes,view:[0,552,0,h]});};
const DESIGNS=dia('Two designs for studying age',[{x:0,y:112,w:150,h:40,text:'Age 20|different people',col:0},{x:200,y:112,w:150,h:40,text:'Age 40|different people',col:0},{x:400,y:112,w:150,h:40,text:'Age 60|different people',col:0},{x:0,y:30,w:150,h:40,text:'Age 4|same children',col:2},{x:200,y:30,w:150,h:40,text:'Age 8|same children',col:2},{x:400,y:30,w:150,h:40,text:'Age 12|same children',col:2}],[[3,4],[4,5]],{notes:[{at:[276,172],text:'cross-sectional: one time, 3 age groups of 25 people'},{at:[276,88],text:'longitudinal: one group, tested at ages 4, 6, 8, 10 and 12'}]});
const ISSUES=board('Big questions in developmental psychology',['Nature and nurture: genes and experience interact','Continuity or stages: gradual change or steps','Stability or change: do traits last over time','Maturation: orderly biological readiness','Critical or sensitive periods: windows of timing','Teratogens: harmful agents before birth']);
const LIFESPAN={t:'timeline',events:['Germinal (to wk 2)','Embryonic (wk 3-8)','Fetal (wk 9-birth)','Puberty','Prime of adulthood','Menopause (~50s)','Late adulthood']};
const GENDERTERMS=board('Sex, gender and orientation: different ideas',['Sex: biological traits (chromosomes, hormones)','Gender identity: inner sense of one\'s gender','Gender role: cultural expectations for behavior','Gender expression: outward presentation','Sexual orientation: pattern of attraction','These are distinct, and people vary on each']);
const NORM=(x,m,s)=>Math.round(Math.exp(-(((x-m)/s)**2)/2)*1e4)/1e4;
const SIMILAR=(()=>{const xs=[];for(let x=55;x<=148;x+=3)xs.push(x);return {t:'plot',title:'Fictional groups: means 100 and 103, SD 15 (d = 0.2)',x:[55,148],y:[0,1],paths:[{pts:xs.map(x=>[x,NORM(x,100,15)]),label:'group A'},{pts:xs.map(x=>[x,NORM(x,103,15)]),label:'group B'}],vlines:[{x:100,dash:true},{x:103,dash:true}]};})();
const PIAGET={t:'timeline',events:['Sensorimotor (0-2)','Preoperational (2-7)','Concrete operational (7-11)','Formal operational (12+)']};
const ZPD=dia('Vygotsky: the zone of proximal development',[{x:0,y:96,w:150,h:46,text:'Can do alone|already learned',col:0},{x:200,y:96,w:150,h:46,text:'Zone of proximal|development: with help',col:1},{x:400,y:96,w:150,h:46,text:'Too hard for now|even with help',col:3}],[[0,1],[1,2]],{notes:[{at:[276,48],text:'scaffolding: help is given, then withdrawn as skill grows'}]});
const LANG={t:'timeline',events:['Cooing ~2 mo','Babbling ~4-6 mo','First words ~12 mo','Two words ~18-24 mo','Sentences ~3 yr']};
const VOCAB={t:'plot',title:'Fictional vocabulary: words known by month',x:[12,24],y:[0,200],paths:[{pts:[[12,10],[18,40],[24,160]],label:'words known'}],points:[{x:18,y:40,label:'speeds up after 18 months'}]};
const ATTACH=bars('Fictional Strange Situation sample (percent of infants)',['Secure','Avoidant','Ambivalent'],[65,20,15]);
const ERIK=board('Erikson\'s eight psychosocial stages (ages approximate)',['1 Trust vs mistrust (infancy)','2 Autonomy vs shame and doubt (toddler)','3 Initiative vs guilt (preschool)','4 Industry vs inferiority (school age)','5 Identity vs role confusion (adolescence)','6 Intimacy vs isolation (young adulthood)','7 Generativity vs stagnation (middle age)','8 Integrity vs despair (late life)']);
const PAVLOV=dia('Classical conditioning in Pavlov\'s dog study',[{x:0,y:112,w:210,h:44,text:'Bell (NS) + food (US)|paired repeatedly',col:0},{x:330,y:112,w:210,h:44,text:'Salivation (UR)|reflex to the food',col:1},{x:0,y:30,w:210,h:44,text:'Bell alone (CS)|after the pairings',col:2},{x:330,y:30,w:210,h:44,text:'Salivation (CR)|learned response',col:3}],[[0,1],[2,3]],{notes:[{at:[276,176],text:'before and during conditioning'},{at:[276,90],text:'after conditioning'}]});
const CURVE=(()=>{const pts=[];for(let n=0;n<=10;n++)pts.push([n,Math.round(100*(1-Math.exp(-n/3))*10)/10]);const top=pts.at(-1)[1];for(let n=11;n<=20;n++)pts.push([n,Math.round(top*Math.exp(-(n-10)/2.5)*10)/10]);pts.push([22,38]);for(let n=23;n<=30;n++)pts.push([n,Math.round(38*Math.exp(-(n-22)/2.5)*10)/10]);return {t:'plot',title:'Schematic classical conditioning curve (strength of the CR)',x:[0,30],y:[0,100],paths:[{pts,label:'CR strength'}],vlines:[{x:10,label:'extinction begins',dash:true},{x:21,label:'rest',dash:true}]};})();
const REINFORCE=board('Operant consequences (add or remove)',['Positive reinforcement: add pleasant, behavior up','Negative reinforcement: remove aversive, up','Positive punishment: add aversive, behavior down','Negative punishment: remove pleasant, down','Positive and negative mean add and remove']);
const SCHED=(()=>{const fr=[[0,0]],fi=[[0,0]];for(let k=0;k<4;k++){fr.push([3*k+1,12*k],[3*k+3,12*k+12]);fi.push([3*k+1.5,12*k+2],[3*k+3,12*k+12]);}return {t:'plot',title:'Schematic cumulative records (responses over time)',x:[0,12],y:[0,50],paths:[{pts:fr,label:'fixed ratio'},{pts:[[0,0],[12,48]],label:'variable ratio'},{pts:fi,label:'fixed interval'},{pts:[[0,0],[12,30]],label:'variable interval'}]};})();
const LEARN=bars('Fictional Bobo-style study: aggressive acts per child',['Aggressive model','Nonaggressive model'],[12,6]);
const WRAP=board('Development and learning checklist',['Method: same people over time, or ages at once','Stage theory: name the stage, then its limits','Attachment and style: caregiver response matters','Conditioning: classical pairs stimuli','Operant: consequence after the behavior','Observation, insight and biology also shape learning']);
const TRY=[
 'Try it: a fictional longitudinal study began with 160 children and 124 children remained at the final session. What percent of the original sample was lost to attrition? Give the number without a percent sign.',
 'Try it: a fictional toddler knew 20 words at 12 months and 74 words at 18 months. What was the average number of new words learned per month?',
 'Try it: a fictional rat is on a fixed-ratio 9 schedule, so every 9th lever press earns a food pellet. How many presses are needed to earn 7 pellets?'
];
export default {
id:'science-h-ap-psych-development-and-learning',subject:'science',level:5,grade:9,standard:'AP Psychology Course and Exam Description (2024-25 onward), Unit 3, topics 3.1–3.9',title:'Development and Learning',
why:'Explain how people change across the lifespan and how they learn, with designs, stage theories and conditioning principles stated with the caution a psychologist would use.',
skills:{methods:'Themes and methods in developmental psychology',physical:'Physical development across the lifespan',gender:'Gender and sexual orientation',cognitive:'Cognitive development across the lifespan',language:'Communication and language development',socialemo:'Social-emotional development across the lifespan',classical:'Classical conditioning',operant:'Operant conditioning',learning:'Social, cognitive and neurological factors in learning'},
outline:[['3.1','Themes and Methods in Developmental Psychology',['methods']],['3.2','Physical Development Across the Lifespan',['physical']],['3.3','Gender and Sexual Orientation',['gender']],['3.4','Cognitive Development Across the Lifespan',['cognitive']],['3.5','Communication and Language Development',['language']],['3.6','Social-Emotional Development Across the Lifespan',['socialemo']],['3.7','Classical Conditioning',['classical']],['3.8','Operant Conditioning',['operant']],['3.9','Social, Cognitive, and Neurological Factors in Learning',['learning']]],
steps:[
 {skill:'methods',say:'Developmental psychologists study how people change over time. In a cross-sectional study, people of different ages are compared at one time, which is fast and cheap but can confuse age with cohort effects, differences due to when people were born. In a longitudinal study, the same people are followed for years, which shows real change within individuals but is slow, costly and can lose participants. In a fictional cross-sectional study with 3 age groups of 25 people, 3 × 25 = 75 people are tested once. A fictional longitudinal study that tests children at ages 4, 6, 8, 10 and 12 has 5 sessions per child.',eq:'3 groups × 25 = 75 people; ages 4, 6, 8, 10, 12 → 5 sessions',pic:DESIGNS},
 {skill:'methods',say:'Several themes recur in this unit. Nature and nurture asks how genes and experience each contribute and interact. Continuity-discontinuity asks whether development is gradual or occurs in distinct stages, and stability-change asks whether traits last. Maturation is the orderly, biologically driven sequence of growth, and a critical (or, more softly, sensitive) period is a window when experience matters most. Teratogens are agents that can harm prenatal development. A longitudinal study that loses participants suffers attrition: if a fictional study starts with 100 children and 80 finish, then 20 ÷ 100 × 100 = 20 percent were lost, and those who stay may differ from those who left.',eq:'(100 − 80) ÷ 100 × 100 = 20 percent attrition',pic:ISSUES,check:{prompt:TRY[0],answer:22.5,options:[22.5,77.5,36],hint:'Subtract the children who remained from the starting number, divide by the starting number, then multiply by 100.',pic:bars('Fictional children in the study',['Start','Final session'],[160,124])}},
 {skill:'physical',say:'Prenatal development has three stages: the germinal stage (roughly the first two weeks, from conception to implantation), the embryonic stage (about weeks 3 to 8, when organs form) and the fetal stage (week 9 to birth). Teratogens such as alcohol, some viruses and some drugs can harm the developing child; heavy alcohol use is linked to fetal alcohol spectrum disorders. Newborns show reflexes such as rooting and sucking, and motor skills follow an orderly maturational sequence. Puberty brings sexual maturation, and the prefrontal cortex continues to mature into the mid-20s. In later adulthood, processing speed usually slows: if a fictional reaction time rises from 160 ms to 200 ms, that is 40 ÷ 160 × 100 = 25 percent slower, while crystallized knowledge often holds up.',eq:'(200 − 160) ÷ 160 × 100 = 25 percent slower',pic:LIFESPAN},
 {skill:'gender',say:'Psychologists distinguish several ideas that people often blur together. Sex refers to biological characteristics such as chromosomes and hormones. Gender identity is a person\'s inner sense of their gender; a person whose gender identity differs from the sex assigned at birth is described as transgender. Gender roles are the behaviors a culture expects, and gender expression is how a person outwardly presents. Sexual orientation is an enduring pattern of attraction to people of the same gender, another gender, or more than one. Mainstream psychology treats these as normal variations, not disorders, and research suggests orientation arises from a mix of biological and environmental influences that is not fully understood.',eq:'sex, gender identity, gender role, gender expression and sexual orientation are separate',pic:GENDERTERMS},
 {skill:'gender',say:'Explanations of how children learn gender roles include social learning theory, in which reinforcement and observing models shape behavior, and gender schema theory, in which children build mental categories for male and female and use them to organize information. Hyde\'s gender similarities hypothesis holds that males and females are alike on most psychological variables, so group differences are usually small compared with differences within each group. Effect size d is the mean difference divided by the standard deviation. For two fictional groups with means 102 and 100 and an SD of 10, d = 2 ÷ 10 = 0.2, a small effect, and the two curves overlap almost completely.',eq:'d = (102 − 100) ÷ 10 = 0.2',pic:SIMILAR},
 {skill:'cognitive',say:'Piaget proposed that children build schemas, mental frameworks, through assimilation (fitting new experiences into existing schemas) and accommodation (changing schemas to fit). He described four stages with approximate ages: sensorimotor (birth to about 2, ending with object permanence), preoperational (about 2 to 7, with symbolic thought but egocentrism and difficulty with conservation), concrete operational (about 7 to 11, logical about concrete things) and formal operational (about 12 on, abstract and hypothetical reasoning). Later research suggests infants and young children can do more, and earlier, than Piaget claimed, and that children do not move through stages as neatly. His ordering of ideas still influences the field, but the ages should be read as rough.',eq:'sensorimotor → preoperational → concrete operational → formal operational',pic:PIAGET},
 {skill:'cognitive',say:'Vygotsky stressed that thinking develops through social interaction and culture. His zone of proximal development is the range of tasks a child cannot yet do alone but can do with guidance, and scaffolding is the support an adult gives and then gradually withdraws. If a fictional child solves 5 puzzles alone and 9 with hints, the zone holds 9 − 5 = 4 puzzles. Related abilities also develop: theory of mind, the understanding that others hold beliefs different from one\'s own, is often tested with false-belief tasks and typically appears around ages 3 to 5, although the timing depends on the task used. In adulthood, fluid abilities tend to decline slowly while crystallized knowledge holds up.',eq:'9 puzzles with help − 5 alone = 4 in the zone',pic:ZPD},
 {skill:'language',say:'Language has building blocks. A phoneme is the smallest unit of sound, a morpheme is the smallest unit of meaning (the word cats has two: cat and -s), syntax is the set of rules for combining words, and semantics is meaning. Infants coo at about 2 months, babble repeated syllables such as ba-ba at about 4 to 6 months, say first words near 12 months, and combine words in short telegraphic speech between about 18 and 24 months, with large individual variation. Mean length of utterance divides morphemes by utterances: in a fictional sample of 30 utterances with 66 morphemes, 66 ÷ 30 = 2.2 morphemes per utterance.',eq:'66 morphemes ÷ 30 utterances = 2.2',pic:LANG},
 {skill:'language',say:'Theories differ on how language is acquired. Skinner argued that children learn language through reinforcement and imitation. Chomsky argued that children are biologically prepared, with a language acquisition device and a universal grammar; children\'s errors such as goed show they apply rules, not only copy. Most researchers now favor an interactionist view in which biology and experience combine. Evidence from people who learn a first language late suggests a sensitive period in early life, though it is not a sharp cutoff. The linguistic relativity hypothesis says language may influence thought, but the strong claim that language determines thought is not supported. Fictional vocabulary growth often speeds up: from 10 words at 12 months to 40 at 18 months is (40 − 10) ÷ 6 = 5 words per month, and to 160 at 24 months is (160 − 40) ÷ 6 = 20.',eq:'(40 − 10) ÷ 6 = 5 words per month, then (160 − 40) ÷ 6 = 20',pic:VOCAB,check:{prompt:TRY[1],answer:9,options:[9,54,4.1],hint:'Subtract the words known at 12 months from the words at 18 months, then divide by the number of months between.',pic:board('Fictional vocabulary',['12 months: 20 words','18 months: 74 words'])}},
 {skill:'socialemo',say:'Attachment is the emotional bond between infant and caregiver. Harlow\'s monkeys preferred a cloth surrogate to a wire one that gave milk, suggesting contact comfort matters more than feeding alone. Ainsworth\'s Strange Situation observes reactions to separation and reunion: securely attached infants use the caregiver as a base and are comforted on return, while insecure infants may avoid or resist the caregiver. In some studies about 60 to 65 percent of infants are classified as secure, and caregiver responsiveness is linked to style, though temperament also matters. In a fictional sample of 100 infants with 65 percent secure, 100 − 65 = 35 are not secure. Baumrind described authoritative, authoritarian and permissive parenting.',eq:'100 infants × 0.65 secure = 65; 100 − 65 = 35 not secure',pic:ATTACH},
 {skill:'socialemo',say:'Erikson proposed eight psychosocial stages, each with a crisis, from trust versus mistrust in infancy to integrity versus despair in late life; in adolescence the task is identity versus role confusion, and in young adulthood intimacy versus isolation. Kohlberg described moral reasoning at three levels: preconventional (avoiding punishment, gaining reward), conventional (following rules and social order) and postconventional (principles beyond particular laws); critics note that his dilemmas favor some cultures, and that people do not always act as they reason. Arnett suggested a period of emerging adulthood, roughly ages 18 to 25. If a fictional person is in stage 4, then 8 − 4 = 4 of the eight stages come after it.',eq:'8 stages − current stage 4 = 4 stages remain',pic:ERIK},
 {skill:'classical',say:'Classical conditioning is learning to link two stimuli. Before conditioning, a bell is a neutral stimulus (NS) that does not trigger salivation. Food is an unconditioned stimulus (US) that naturally produces salivation, the unconditioned response (UR). When the bell is repeatedly paired with food, the bell becomes a conditioned stimulus (CS) and salivating to it alone is the conditioned response (CR). Pavlov\'s work showed that conditioning depends on association, and later work by Rescorla stressed that the CS must predict the US, not just occur near it. If a fictional experiment gives 10 pairings per session for 7 sessions, that is 10 × 7 = 70 pairings.',eq:'10 pairings × 7 sessions = 70 pairings',pic:PAVLOV},
 {skill:'classical',say:'During acquisition the CR gets stronger across pairings. In extinction the CS appears without the US and the CR fades, but after a rest the CR may return briefly, called spontaneous recovery. Generalization is responding to stimuli similar to the CS, and discrimination is responding only to the CS. Watson and Rayner\'s 1920 Little Albert study paired a white rat with a loud noise and is cited as showing that emotional responses can be learned, but it is now considered unethical, and its details are criticized. Conditioned taste aversion, studied by Garcia, can form after one pairing and long delays, and counterconditioning replaces a fear with a calmer response. If a fictional CR falls from 20 to 6 over 7 extinction trials, the average drop is 14 ÷ 7 = 2 per trial.',eq:'(20 − 6) ÷ 7 = 2 per trial',pic:CURVE},
 {skill:'operant',say:'Operant conditioning is learning from consequences. Thorndike\'s law of effect says behavior followed by satisfying outcomes becomes more likely, and Skinner studied it with rats and pigeons in a controlled box. Reinforcement increases behavior and punishment decreases it. The words positive and negative mean adding or removing a stimulus, not good or bad. Praise after chores is positive reinforcement; taking a pill that ends a headache is negative reinforcement, because relief strengthens pill-taking; a speeding ticket is positive punishment; losing phone privileges is negative punishment. Shaping rewards successive approximations of a target behavior. Punishment can suppress behavior but may cause fear and does not teach what to do instead.',eq:'add or remove a stimulus; reinforcement raises, punishment lowers',pic:REINFORCE},
 {skill:'operant',say:'A schedule of reinforcement tells when a behavior earns its consequence. Fixed ratio rewards every nth response and gives a high rate with a pause after each reward; variable ratio rewards after an unpredictable number of responses, as with a slot machine, and gives high, steady responding. Fixed interval rewards the first response after a set time and produces scalloped records; variable interval rewards after unpredictable times, with moderate, steady responding. Partial reinforcement resists extinction more than continuous reinforcement, especially on variable schedules. On a fixed-ratio 6 schedule, 4 rewards need 6 × 4 = 24 responses; on a fixed-interval 4-minute schedule, steady responding for 22 minutes earns at most 5 rewards.',eq:'FR 6 × 4 rewards = 24 responses; 22 ÷ 4 = 5 full intervals',pic:SCHED,check:{prompt:TRY[2],answer:63,options:[63,16,54],hint:'On a fixed-ratio schedule, multiply the responses required per reward by the number of rewards.',pic:board('Fixed-ratio schedule (fictional)',['one pellet per 9 presses','goal: 7 pellets'])}},
 {skill:'learning',say:'Learning also involves watching, thinking and biology. Bandura\'s Bobo doll studies showed observational learning: children who saw an adult act aggressively often imitated that aggression, and seeing a model rewarded is vicarious reinforcement. Mirror neurons fire both when an animal performs an action and when it watches one; they were found in monkeys, evidence in humans is indirect, and their exact role in imitation is debated. Tolman\'s rats showed latent learning and cognitive maps, and Köhler\'s chimpanzees showed insight. Rescorla showed that prediction matters in conditioning, and Garcia showed biological preparedness. Dopamine pathways are linked to reward signaling, and extra rewards can sometimes reduce interest, the overjustification effect. In a fictional study with means of 12 and 6 acts, (12 − 6) ÷ 6 × 100 = 100 percent more.',eq:'(12 − 6) ÷ 6 × 100 = 100 percent higher',pic:LEARN},
 {skill:'learning',summary:true,say:'To work through this unit, name the kind of question first. For a research design, ask whether the same people were followed or different ages were compared at once, and watch for cohort effects and attrition. For a developmental theory, name the stage or style and remember the caution about ages and cultures. For conditioning, label NS, US, UR, CS and CR in order, then check whether a consequence came after the behavior, which makes it operant. For schedules, count responses or intervals. Treat Piaget\'s ages, the Little Albert study and mirror-neuron claims as findings to weigh, and use calm, respectful, scientific language about gender and orientation.',eq:'name the design or stimuli first, then the stage or schedule, then weigh the evidence',pic:WRAP}
],
progression:{requires:['science-h-ap-psych-cognition'],operations:3,demand:'Compare research designs, match developmental theories to evidence, label conditioning and reinforcement, and compute attrition, rates and reinforcement counts from stated data.'},
items(add){/* Round 11 (17 Oct): a pool rounding instruction never asks for more decimals than the stored answer has; "if needed" and significant-figure instructions are kept. Same copy in every unit that uses it (tests/pool-wording-round11.test.js). */const fitRound=(p,a)=>{if(typeof a!=='number'||!Number.isFinite(a)||/if needed/i.test(p))return p;const s=String(a);if(/e/.test(s))return p;const d=(s.split('.')[1]||'').length,W=['zero','one','two','three','four'],NEAR=['whole number','tenth','hundredth','thousandth','ten-thousandth'],m=/(, )?(\b(?:and )?(?:rounded|[Rr]ound) )?to (?:the nearest (tenth|hundredth|thousandth|ten-thousandth)( of a unit)?|(\d|one|two|three|four) (decimal places?|decimals?)\b)/.exec(p);if(!m)return p;const asked=m[3]?NEAR.indexOf(m[3]):/\d/.test(m[5])?+m[5]:W.indexOf(m[5]);if(asked<=d)return p;const head=p.slice(0,m.index),tail=p.slice(m.index+m[0].length);if(d>0)return head+m[0].replace(m[3]||m[5]+' '+m[6],m[3]?NEAR[d]:(/\d/.test(m[5])?d:W[d])+' '+(d===1?'decimal place':m[6]==='decimals'?'decimals':'decimal places'))+tail;const whole=[[/(^|[.?!;] )Give a decimal $/,'$1Give a whole number'],[/(^|[.?!] )Give the number without a percent sign $/,'$1Give a whole number without a percent sign'],[/(^|[.?!] )Give a signed number$/,'$1Give a signed whole number'],[/ as a percent $/,' as a whole-number percent'],[/(^|[.?!] )Give (?:the number|the answer|your answer|it) $/,'$1Give a whole number'],[/(^|[.?!] )(Give [^.?!,]*) $/,'$1$2 as a whole number']];for(const [re,w] of whole)if(re.test(head))return head.replace(re,w)+tail;if(m[2]&&/^[.?!]/.test(tail)&&/(^|[.?!;)] )$/.test(head))return head+(/; $/.test(head)?'give':'Give')+' a whole number'+tail;return head.replace(/ $/,'')+(m[1]?',':'')+(m[2]&&/^and /.test(m[2])?' and give a whole number':' as a whole number'+(m[4]?' of units':''))+tail;};const put0=add;add=(s,p,a,...r)=>put0(s,fitRound(p,a),a,...r);const seen=new Set(TRY);const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 for(const [skill,rows] of Object.entries(FACTS))rows.forEach(([prompt,right,w1,w2,explanation],i)=>{const c=choose(right,[w1,w2],i);put(skill,`${prompt} ${c.text}. Answer A, B or C.`,c.letter,scenario('Read the question',prompt),explanation,[right]);});
 const R=' Give the number without a percent sign and round to four decimals.';
 for(const [n,m] of [[200,138],[120,87],[250,210]])put('methods',`A fictional longitudinal study began with ${n} children and ${m} children remained at the final session. What percent of the original sample was lost to attrition?${R}`,rnd((n-m)/n*100),bars('Fictional children in the study',['Start','Final session'],[n,m]),`Children lost = ${n} − ${m} = ${n-m}, so ${n-m} ÷ ${n} × 100 = ${rnd((n-m)/n*100)} percent. Attrition can bias a longitudinal sample if those who leave differ from those who stay.`);
 for(const [k,a,b] of [[2,4,16],[3,6,18],[5,5,20]])put('methods',`A fictional longitudinal study measures each child every ${k} years from age ${a} through age ${b}, including both ages. How many measurement sessions does each child complete? Round to four decimals.`,(b-a)/k+1,board('Fictional schedule',[`every ${k} years`,`from age ${a} through age ${b}`]),`From ${a} to ${b} is ${b-a} years, which is ${(b-a)/k} gaps of ${k} years. Counting both ends adds one session: ${(b-a)/k} + 1 = ${(b-a)/k+1}.`);
 for(const [g,n] of [[4,30],[5,24],[6,18]])put('methods',`A fictional cross-sectional study tests ${g} age groups with ${n} participants in each group. How many participants are tested in total? Round to four decimals.`,g*n,bars('Fictional design',['Age groups','Per group'],[g,n]),`Each person is tested once, so the total is ${g} × ${n} = ${g*n} participants.`);
 for(const [a,b,m] of [[50,75,12],[49,67,9],[51,66,8]])put('physical',`A fictional infant measured ${a} cm at birth and ${b} cm at ${m} months. What was the average growth in centimeters per month? Round to four decimals.`,rnd((b-a)/m),bars('Fictional length (cm)',['Birth',`${m} months`],[a,b]),`Growth = ${b} − ${a} = ${b-a} cm over ${m} months, so ${b-a} ÷ ${m} = ${rnd((b-a)/m)} cm per month. Real growth varies from child to child.`);
 for(const [a,b,x,y] of [[240,300,25,75],[250,290,30,70],[200,270,20,80]])put('physical',`A fictional adult's mean reaction time rose from ${a} ms at age ${x} to ${b} ms at age ${y}. By what percent did the reaction time increase?${R}`,rnd((b-a)/a*100),bars('Fictional reaction time (ms)',[`Age ${x}`,`Age ${y}`],[a,b]),`Increase = ${b} − ${a} = ${b-a} ms, so ${b-a} ÷ ${a} × 100 = ${rnd((b-a)/a*100)} percent. Speed of processing tends to slow with age, though people differ widely.`);
 for(const [t,s] of [[38,9],[40,9],[36,9]])put('physical',`In a fictional timeline of a ${t}-week pregnancy, the fetal stage begins at week ${s} and lasts until birth at week ${t}. How many weeks does the fetal stage last? Round to four decimals.`,t-s,bars('Fictional weeks',['Birth week','Fetal stage starts'],[t,s]),`The fetal stage lasts from week ${s} to week ${t}, so ${t} − ${s} = ${t-s} weeks in this fictional timeline.`);
 for(const [n,k] of [[250,215],[400,332],[120,105]])put('gender',`In a fictional survey of ${n} adults, ${k} agreed that boys and girls should have equal access to every school activity. What percent agreed?${R}`,rnd(k/n*100),bars('Fictional survey',['Agreed','Did not agree'],[k,n-k]),`${k} ÷ ${n} × 100 = ${rnd(k/n*100)} percent agreed. A percent from a survey describes opinions in that sample only.`);
 for(const [m1,m2,sd] of [[52,50,10],[105,100,15],[71,68,12]])put('gender',`In a fictional study, one group's mean score on a spatial task was ${m1} and the other group's mean was ${m2}, with a standard deviation of ${sd} in both groups. What is the effect size d, the mean difference divided by the standard deviation? Round to four decimals.`,rnd((m1-m2)/sd),bars('Fictional group means',['Group one','Group two'],[m1,m2]),`d = (${m1} − ${m2}) ÷ ${sd} = ${rnd((m1-m2)/sd)}. A d this small means the groups overlap heavily, which fits the gender similarities hypothesis.`);
 for(const [a,n,b] of [[18,40,24],[30,50,36],[21,60,33]])put('gender',`In a fictional play observation, ${a} of ${n} girls and ${b} of ${n} boys chose the building-block activity. By how many percentage points do the two shares differ? Give the positive difference and round to four decimals.`,rnd(Math.abs(b-a)/n*100),bars('Fictional children choosing blocks',['Girls','Boys'],[a,b]),`The shares are ${rnd(a/n*100)} percent and ${rnd(b/n*100)} percent, so they differ by ${rnd(Math.abs(b-a)/n*100)} percentage points. Many children of both groups made each choice.`);
 for(const [a,b] of [[4,10],[6,9],[3,12]])put('cognitive',`A fictional child can solve ${a} puzzles alone and ${b} puzzles when an adult gives hints; the count with hints includes the ${a} solved alone. How many puzzles lie in the child's zone of proximal development, solved with help but not alone? Round to four decimals.`,b-a,bars('Fictional puzzles solved',['Alone','With hints'],[a,b]),`The zone is the tasks done only with help: ${b} − ${a} = ${b-a} puzzles. Scaffolding would be reduced as these become independent.`);
 for(const [a,n,b] of [[6,40,30],[9,60,48],[10,50,35]])put('cognitive',`In a fictional study, ${a} of ${n} five-year-olds and ${b} of ${n} eight-year-olds passed a conservation task. By how many percentage points was the older group's pass rate higher? Round to four decimals.`,rnd((b-a)/n*100),bars('Fictional conservation passes',['Age five','Age eight'],[a,b]),`The pass rates are ${rnd(a/n*100)} percent and ${rnd(b/n*100)} percent, a gap of ${rnd((b-a)/n*100)} points. Task wording can change how many younger children pass.`);
 for(const [k,n] of [[27,36],[18,40],[21,60]])put('cognitive',`In a fictional false-belief task, ${k} of ${n} four-year-olds answered correctly. What percent answered correctly?${R}`,rnd(k/n*100),bars('Fictional false-belief task',['Correct','Incorrect'],[k,n-k]),`${k} ÷ ${n} × 100 = ${rnd(k/n*100)} percent. Theory-of-mind results depend on the task used.`);
 for(const [w1,m1,w2,m2] of [[10,12,76,18],[50,18,260,24],[4,10,40,16]])put('language',`A fictional toddler knew ${w1} words at ${m1} months and ${w2} words at ${m2} months. What was the average number of new words learned per month? Round to four decimals.`,rnd((w2-w1)/(m2-m1)),bars('Fictional words known',[`${m1} months`,`${m2} months`],[w1,w2]),`New words = ${w2} − ${w1} = ${w2-w1} over ${m2-m1} months, so ${w2-w1} ÷ ${m2-m1} = ${rnd((w2-w1)/(m2-m1))} per month. Real children differ widely.`);
 for(const [r,w,m] of [[8,50,6],[12,100,4],[15,30,10]])put('language',`A fictional child learns ${r} new words per month at a constant rate. If the child knows ${w} words now, how many words will the child know after ${m} more months? Round to four decimals.`,w+r*m,bars('Fictional vocabulary plan',['Words now','New per month'],[w,r]),`New words = ${r} × ${m} = ${r*m}, so ${w} + ${r*m} = ${w+r*m} words. Real vocabulary growth is rarely perfectly constant.`);
 for(const [u,t] of [[50,95],[40,128],[25,60]])put('language',`In a fictional language sample, a child produced ${u} utterances containing ${t} morphemes in total. What is the mean length of utterance, in morphemes per utterance? Round to four decimals.`,rnd(t/u),bars('Fictional language sample',['Utterances','Morphemes'],[u,t]),`MLU = ${t} ÷ ${u} = ${rnd(t/u)} morphemes per utterance, a rough index of grammatical growth.`);
 for(const [n,k] of [[60,39],[80,54],[45,27]])put('socialemo',`In a fictional sample of ${n} infants observed in a Strange Situation-style procedure, ${k} were classified as securely attached. What percent were securely attached?${R}`,rnd(k/n*100),bars('Fictional attachment sample',['Secure','Not secure'],[k,n-k]),`${k} ÷ ${n} × 100 = ${rnd(k/n*100)} percent were classified as secure.`);
 for(const [n,p] of [[80,60],[150,70],[200,65]])put('socialemo',`In a fictional sample of ${n} infants, ${p} percent were classified as securely attached. How many infants were not classified as securely attached? Round to four decimals.`,rnd(n*(100-p)/100),bars('Fictional percent secure',['Secure','Not secure'],[p,100-p]),`The not-secure share is ${100-p} percent, so ${n} × ${(100-p)/100} = ${rnd(n*(100-p)/100)} infants.`);
 for(const k of [3,5,6])put('socialemo',`Erikson proposed eight psychosocial stages. If a fictional person is currently in stage ${k}, how many of the eight stages come after the current one? Round to four decimals.`,8-k,bars('Fictional position among the stages',['Current stage','Total stages'],[k,8]),`Stages after stage ${k} are 8 − ${k} = ${8-k}, since Erikson proposed eight in all.`);
 for(const [n,s] of [[12,5],[8,9],[15,6]])put('classical',`In a fictional conditioning experiment, a tone was paired with a puff of air ${n} times per session across ${s} sessions. How many tone-puff pairings occurred in total? Round to four decimals.`,n*s,bars('Fictional pairings',['Per session','Sessions'],[n,s]),`Total pairings = ${n} × ${s} = ${n*s}. Repeated pairing is how a neutral stimulus becomes a conditioned stimulus.`);
 for(const [k,n] of [[18,24],[21,30],[9,40]])put('classical',`In a fictional classical conditioning study, a dog salivated to the tone alone on ${k} of ${n} test trials. What percent of the test trials produced the conditioned response?${R}`,rnd(k/n*100),bars('Fictional test trials',['CR','No CR'],[k,n-k]),`${k} ÷ ${n} × 100 = ${rnd(k/n*100)} percent of trials showed the CR.`);
 for(const [a,b,t] of [[24,6,9],[30,12,6],[18,3,10]])put('classical',`During extinction in a fictional study, the conditioned response dropped from ${a} drops of saliva to ${b} drops over ${t} tone-alone trials. What was the average drop per trial? Round to four decimals.`,rnd((a-b)/t),bars('Fictional drops of saliva',['Start of extinction','End of extinction'],[a,b]),`The drop is ${a} − ${b} = ${a-b} drops over ${t} trials, so ${a-b} ÷ ${t} = ${rnd((a-b)/t)} per trial.`);
 for(const [n,r] of [[5,8],[12,6],[20,4]])put('operant',`A fictional rat is on a fixed-ratio ${n} schedule, so every ${n}th lever press earns a food pellet. How many presses are needed to earn ${r} pellets? Round to four decimals.`,n*r,bars('Fictional schedule',['Presses per pellet','Pellets'],[n,r]),`Each pellet needs ${n} presses, so ${r} pellets need ${n} × ${r} = ${n*r} presses.`);
 for(const [n,r] of [[8,5],[25,4],[10,12]])put('operant',`A fictional game pays out on a variable-ratio schedule averaging ${n} plays per payout. About how many plays are expected for ${r} payouts? Round to four decimals.`,n*r,bars('Fictional variable-ratio game',['Plays per payout (average)','Payouts'],[n,r]),`On average ${n} plays are needed per payout, so about ${n} × ${r} = ${n*r} plays are expected. The actual number varies.`);
 for(const [m,T] of [[5,30],[10,45],[8,50]])put('operant',`A fictional pigeon works on a fixed-interval ${m}-minute schedule: the first peck after each ${m} minutes have passed earns food, and the interval restarts after each reward. If the pigeon pecks steadily for ${T} minutes, at most how many food rewards can it earn? Round to four decimals.`,Math.floor(T/m),bars('Fictional session (minutes)',['Interval','Session'],[m,T]),`Each reward needs a full ${m}-minute interval, so ${T} ÷ ${m} has ${Math.floor(T/m)} complete intervals. The leftover time earns nothing more.`);
 for(const [a,b,t] of [[20,35,10],[40,50,15],[16,28,20]])put('operant',`A fictional rat pressed a lever ${a} times in ${t} minutes before reinforcement began and ${b} times in ${t} minutes after reinforcement began. By what percent did the number of presses increase?${R}`,rnd((b-a)/a*100),bars('Fictional lever presses',['Before reinforcement','After reinforcement'],[a,b]),`Increase = ${b} − ${a} = ${b-a}, so ${b-a} ÷ ${a} × 100 = ${rnd((b-a)/a*100)} percent.`);
 for(const [a,b] of [[14,8],[9,6],[10,4]])put('learning',`In a fictional Bobo-style study, children who watched an aggressive model averaged ${a} aggressive acts and children who watched a nonaggressive model averaged ${b}. By what percent was the first group's average higher than the second group's?${R}`,rnd((a-b)/b*100),bars('Fictional aggressive acts',['Aggressive model','Nonaggressive model'],[a,b]),`The difference is ${a} − ${b} = ${a-b}, so ${a-b} ÷ ${b} × 100 = ${rnd((a-b)/b*100)} percent higher than the comparison group.`);
 for(const [a,b] of [[10,4],[8,5],[12,3]])put('learning',`In a fictional Tolman-style maze study, rats made a mean of ${a} errors per trial on the last day without reward and ${b} errors on the first day after food was introduced. By what percent did the mean number of errors fall?${R}`,rnd((a-b)/a*100),bars('Fictional mean errors',['Last day, no reward','First day, reward'],[a,b]),`The drop is ${a} − ${b} = ${a-b}, so ${a-b} ÷ ${a} × 100 = ${rnd((a-b)/a*100)} percent. A sudden fall suggests the rats had learned the maze earlier without showing it.`);
 for(const [n,k] of [[40,6],[80,14],[25,2]])put('learning',`In a fictional recording of ${n} neurons in a motor area, ${k} fired both when a monkey grasped an object and when it watched a person grasp it. What percent of the recorded neurons fired in both situations?${R}`,rnd(k/n*100),bars('Fictional neurons',['Fired in both','Other'],[k,n-k]),`${k} ÷ ${n} × 100 = ${rnd(k/n*100)} percent. Cells like these are called mirror neurons, and their role in humans is still debated.`);
}
};
